。</p><h2 id="goroutines">Goroutine 深度解析</h2><p>Goroutine 是 Go 运行时管理的轻量级执行单元。创建 Goroutine 非常简单，只需在函数调用前加上 go 关键字。</p><h3>基础用法</h3><pre><code>package main

import (
    "fmt"
    "time"
)

func sayHello(name string) {
    for i := 0; i < 5; i++ {
        fmt.Printf("Hello, %s!\n", name)
        time.Sleep(100 * time.Millisecond)
    }
}

func main() {
    // 启动一个 goroutine
    go sayHello("Alice")

    // 主 goroutine 继续执行
    sayHello("Bob")

    // 主函数退出时，所有其他 goroutine 也会终止
    // 需要等待 goroutine 完成
}

// 正确的等待模式
func main() {
    done := make(chan bool)

    go func() {
        // 执行任务
        time.Sleep(time.Second)
        done <- true
    }()

    <-done // 等待 goroutine 完成
    fmt.Println("任务完成")
}
</code></pre><h3>Goroutine 调度</h3><p>Go 使用 GMP 模型进行调度：G（Goroutine）、M（Machine，操作系统线程）、P（Processor，调度上下文）。调度器维护一个运行队列，将可运行的 Goroutine 分派到可用的 P 上执行。这种设计允许 Goroutine 在不同的 M 之间迁移，从而实现高效的负载均衡和系统调用处理。</p><p>Goroutine 的调度是非抢占式的，这意味着一个 Goroutine 会一直运行直到它主动让出控制权（如通过 Channel 操作、time.Sleep 或 runtime.Gosched）。对于需要长时间运行的 CPU 密集型任务，需要显式调用 runtime.Gosched() 或使用其他同步机制来让出 CPU。</p><pre><code>package main

import (
    "fmt"
    "runtime"
    "time"
)

func cpuIntensive() {
    // CPU 密集型计算
    sum := 0
    for i := 0; i < 1e9; i++ {
        sum += i
        // 每100万次迭代让出一次 CPU
        if i%1e6 == 0 {
            runtime.Gosched()
        }
    }
    fmt.Println("计算完成:", sum)
}

func main() {
    // 设置 GOMAXPROCS
    // 对于 CPU 密集型任务，应该设置为 CPU 核心数
    // 对于 IO 密集型任务，可以设置为更高
    numCPU := runtime.NumCPU()
    runtime.GOMAXPROCS(numCPU)

    fmt.Printf("使用 %d 个 CPU 核心\n", numCPU)

    start := time.Now()

    // 并行执行多个 CPU 密集型任务
    done := make(chan bool, 4)
    for i := 0; i < 4; i++ {
        go func(id int) {
            fmt.Printf("任务 %d 开始\n", id)
            cpuIntensive()
            fmt.Printf("任务 %d 完成\n", id)
            done <- true
        }(i)
    }

    // 等待所有任务完成
    for i := 0; i < 4; i++ {
        <-done
    }

    fmt.Printf("总耗时: %v\n", time.Since(start))
}
</code></pre><h2 id="channels">Channel 通道详解</h2><p>Channel 是 Go 中实现 Goroutine 通信的核心机制。它可以被看作是一个管道，通过它 Goroutine 可以发送和接收值。</p><h3>Channel 创建与操作</h3><pre><code>package main

import "fmt"

func main() {
    // 创建无缓冲 channel
    ch1 := make(chan int)

    // 创建有缓冲 channel
    ch2 := make(chan int, 10)

    // channel 操作
    // 发送: ch <- value
    // 接收: <-ch
    // 关闭: close(ch)

    // 单向 channel（类型注解）
    // chan<- int  // 只能发送
    // <-chan int  // 只能接收

    // 生产者函数
    producer := func(ch chan<- int) {
        for i := 0; i < 5; i++ {
            ch <- i  // 发送数据
        }
        close(ch)  // 关闭 channel
    }

    // 消费者函数
    consumer := func(ch <-chan int) {
        for v := range ch {  // range 会自动检测 channel 关闭
            fmt.Printf("收到: %d\n", v)
        }
    }

    ch := make(chan int)
    go producer(ch)
    consumer(ch)
}

// 多个生产者多个消费者
func multiProducerConsumer() {
    type Task struct {
        ID   int
        Data string
    }

    taskCh := make(chan Task, 100)
    resultCh := make(chan string, 100)

    // 启动 3 个生产者
    for i := 0; i < 3; i++ {
        go func(id int) {
            for j := 0; j < 10; j++ {
                task := Task{ID: id*10 + j, Data: fmt.Sprintf("task-%d", j)}
                taskCh <- task
            }
        }(i)
    }

    // 启动 5 个消费者
    for i := 0; i < 5; i++ {
        go func(id int) {
            for task := range taskCh {
                // 处理任务
                result := fmt.Sprintf("处理者-%d 处理了任务 %d", id, task.ID)
                resultCh <- result
            }
        }(i)
    }

    // 等待并收集结果
    for i := 0; i < 30; i++ {
        fmt.Println(<-resultCh)
    }
}
</code></pre><h3>Channel 底层实现</h3><p>理解 Channel 的底层实现有助于更好地使用它。Channel 的内部结构包含一个环形缓冲区、发送等待队列和接收等待队列。当缓冲区满时，发送操作会阻塞；当缓冲区为空时，接收操作会阻塞。</p><pre><code>// Channel 内部结构（简化版）
type hchan struct {
    qcount   uint           // 缓冲区中的元素数量
    dataqsiz uint           // 环形缓冲区大小
    buf      unsafe.Pointer // 指向缓冲区的指针
    elemsize uint16         // 元素大小
    closed   uint32         // 是否已关闭
    elemtype *_type         // 元素类型
    sendq    waitq          // 发送等待队列
    recvq    waitq          // 接收等待队列
    lock     mutex          // 保护所有字段的互斥锁
}

type waitq struct {
    first *sudog  // 队列头
    last  *sudog  // 队列尾
}

// Channel 的发送和接收过程
// 1. 获取锁
// 2. 如果有等待的接收者，直接拷贝值（绕过缓冲区）
// 3. 如果缓冲区有空间，将值拷贝到缓冲区
// 4. 否则，将自己添加到发送等待队列并阻塞
// 5. 释放锁

// 理解这些机制有助于避免死锁和优化性能
</code></pre><h2 id="select-statement">Select 语句与多路复用</h2><p>select 语句是 Go 中处理多个 Channel 操作的强大工具，类似于 switch 但用于 Channel。</p><h3>基础 select</h3><pre><code>package main

import (
    "fmt"
    "time"
)

func basicSelect() {
    ch1 := make(chan string, 1)
    ch2 := make(chan string, 1)

    go func() {
        time.Sleep(1 * time.Second)
        ch1 <- "消息1"
    }()

    go func() {
        time.Sleep(2 * time.Second)
        ch2 <- "消息2"
    }()

    // select 会阻塞，直到某个 case 可以执行
    // 如果多个 case 同时就绪，随机选择一个执行
    select {
    case msg1 := <-ch1:
        fmt.Println("收到:", msg1)
    case msg2 := <-ch2:
        fmt.Println("收到:", msg2)
    case <-time.After(3 * time.Second):
        fmt.Println("超时")
    }
}

// 发送超时控制
func sendWithTimeout(ch chan<- int, value, timeout int) bool {
    select {
    case ch <- value:
        return true
    case <-time.After(time.Duration(timeout) * time.Second):
        return false
    }
}

// 非阻塞发送和接收
func nonBlocking() {
    ch := make(chan int, 1)

    // 非阻塞发送
    select {
    case ch <- 42:
        fmt.Println("发送成功")
    default:
        fmt.Println("通道已满，发送被跳过")
    }

    // 非阻塞接收
    select {
    case v := <-ch:
        fmt.Println("接收:", v)
    default:
        fmt.Println("通道为空，接收被跳过")
    }
}
</code></pre><h3>优雅关闭 Channel</h3><pre><code>package main

import (
    "fmt"
    "sync"
)

// 确保所有 worker 都正确关闭的模式
func workerPool() {
    jobs := make(chan int, 100)
    results := make(chan int, 100)

    // 启动 worker 池
    numWorkers := 3
    var wg sync.WaitGroup

    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            for job := range jobs {
                // 处理任务
                result := job * 2
                results <- result
            }
        }(i)
    }

    // 发送所有任务
    go func() {
        for i := 1; i <= 10; i++ {
            jobs <- i
        }
        close(jobs)  // 关闭 jobs channel
    }()

    // 在单独的 goroutine 中关闭 results
    go func() {
        wg.Wait()  // 等待所有 worker 完成
        close(results)  // 关闭 results channel
    }()

    // 收集结果
    for result := range results {
        fmt.Println("结果:", result)
    }
}

// 使用 context 取消 channel 操作
