}
</code></pre><h2 id="context-package">Context 包实战</h2><p>context 包是 Go 1.7 引入的，用于在 API 边界之间传递截止时间、取消信号和请求作用域值。它是构建可取消和可超时操作的核心工具。</p><h3>Context 基础</h3><pre><code>package main

import (
    "context"
    "fmt"
    "time"
)

func contextBasics() {
    // 创建带超时的 context
    ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
    defer cancel()  // 重要：总是调用 cancel 释放资源

    select {
    case <-time.After(1 * time.Second):
        fmt.Println("1秒后")
    case <-ctx.Done():
        fmt.Println("Context 已取消:", ctx.Err())
    }
}

// HTTP 服务器中使用 context
func httpWithContext() {
    // ctx, cancel := context.WithCancel(context.Background())
    // defer cancel()

    // 模拟处理请求
    // 某些情况下需要取消请求，比如客户端断开连接
}

// Context 树结构
func contextTree() {
    // 根 Context
    rootCtx := context.Background()

    // 从 rootCtx 创建带取消的 context
    ctx1, cancel1 := context.WithCancel(rootCtx)

    // 从 ctx1 创建带超时的 context
    ctx2, cancel2 := context.WithTimeout(ctx1, 5*time.Second)

    // 从 ctx2 创建带值的 context
    ctx3 := context.WithValue(ctx2, "userID", "12345")

    // 取消 ctx1 会导致 ctx2 和 ctx3 也被取消
    // 但取消 ctx2 不会影响 ctx1

    defer cancel1()
    defer cancel2()

    // 使用 ctx3
    userID := ctx3.Value("userID")
    fmt.Println("User ID:", userID)
}

// 完整示例：带超时的 HTTP 请求
func fetchWithTimeout(url string, timeout time.Duration) (string, error) {
    ctx, cancel := context.WithTimeout(context.Background(), timeout)
    defer cancel()

    req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
    if err != nil {
        return "", err
    }

    client := &http.Client{Timeout: timeout}
    resp, err := client.Do(req)
    if err != nil {
        return "", err
    }
    defer resp.Body.Close()

    body, err := io.ReadAll(resp.Body)
    return string(body), err
}
</code></pre><h3>Context 在并发中的应用</h3><pre><code>package main

import (
    "context"
    "fmt"
    "sync"
    "time"
)

// 使用 context 控制多个 goroutine
func parallelWorkers() {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    results := make(chan string, 5)
    var wg sync.WaitGroup

    // 启动多个 worker
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()

            for {
                select {
                case <-ctx.Done():
                    fmt.Printf("Worker %d 收到取消信号\n", id)
                    return
                default:
                    // 执行工作
                    time.Sleep(500 * time.Millisecond)
                    results <- fmt.Sprintf("Worker %d 完成", id)
                }
            }
        }(i)
    }

    // 模拟主逻辑
    time.Sleep(2 * time.Second)
    fmt.Println("主逻辑完成，取消所有 worker")
    cancel()

    wg.Wait()
    close(results)

    for r := range results {
        fmt.Println(r)
    }
}

// 带优先级的任务处理
func priorityTasks() {
    highPriority := make(chan string, 10)
    lowPriority := make(chan string, 10)

    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    processTask := func(task string) {
        time.Sleep(100 * time.Millisecond)
        fmt.Printf("处理: %s\n", task)
    }

    for {
        select {
        case task := <-highPriority:
            processTask(task)
        case task := <-lowPriority:
            // 检查是否有高优先级任务等待
            select {
            case ht := <-highPriority:
                processTask(ht)
                processTask(task)
            default:
                processTask(task)
            }
        case <-ctx.Done():
            fmt.Println("超时退出")
            return
        }
    }
}
</code></pre><h2 id="sync-patterns">同步与并发模式</h2><p>虽然 Go 鼓励使用 Channel 进行通信，但在某些场景下，传统的同步原语（Mutex、WaitGroup、Once 等）仍然是更好的选择。</p><h3>sync.WaitGroup</h3><pre><code>package main

import (
    "fmt"
    "sync"
)

func waitGroupDemo() {
    var wg sync.WaitGroup

    // 添加计数器
    wg.Add(3)

    for i := 0; i < 3; i++ {
        go func(id int) {
            defer wg.Done()  // 完成后递减计数器
            fmt.Printf("Goroutine %d 开始\n", id)
            // 模拟工作
            for j := 0; j < 3; j++ {
                fmt.Printf("  Worker %d: %d\n", id, j)
            }
            fmt.Printf("Goroutine %d 结束\n", id)
        }(i)
    }

    // 等待所有 goroutine 完成
    wg.Wait()
    fmt.Println("所有任务完成")
}

// 常见错误：WaitGroup 计数器不一致
func waitGroupMistakes() {
    // 错误：在 goroutine 内部调用 Add
    var wg sync.WaitGroup
    for i := 0; i < 5; i++ {
        // 错误！应该先 Add
        go func(id int) {
            wg.Add(1)  // 不推荐这样做
            defer wg.Done()
            // work
        }(i)
    }

    // 正确做法：先 Add，再启动 goroutine
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            // work
        }(i)
    }

    wg.Wait()
}
</code></pre><h3>sync.Mutex 和 sync.RWMutex</h3><pre><code>package main

import (
    "fmt"
    "sync"
)

type Counter struct {
    mu    sync.Mutex
    value int
}

// 简单互斥
func (c *Counter) Inc() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.value++
}

func (c *Counter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.value
}

// 读写锁：读操作可以并发，写操作需要独占
type SafeMap struct {
    mu sync.RWMutex
    data map[string]string
}

func (m *SafeMap) Set(key, value string) {
    m.mu.Lock()
    defer m.mu.Unlock()
    m.data[key] = value
}

func (m *SafeMap) Get(key string) string {
    m.mu.RLock()
    defer m.mu.RUnlock()
    return m.data[key]
}

func (m *SafeMap) GetAll() map[string]string {
    m.mu.RLock()
    defer m.mu.RUnlock()
    result := make(map[string]string, len(m.data))
    for k, v := range m.data {
        result[k] = v
    }
    return result
}

// 使用 sync.Map（针对读多写少场景优化）
func syncMapExample() {
    var sm sync.Map

    // 存储
    sm.Store("key1", "value1")
    sm.Store("key2", "value2")

    // 加载
    if v, ok := sm.Load("key1"); ok {
        fmt.Println("Found:", v)
    }

    // 加载或存储
    v, loaded := sm.LoadOrStore("key1", "newValue")
    fmt.Printf("Value: %s, Loaded: %v\n", v, loaded)

    // 遍历
    sm.Range(func(k, v interface{}) bool {
        fmt.Printf("%s: %s\n", k, v)
        return true
    })

    // 删除
    sm.Delete("key2")
}
</code></pre><h3>sync.Once 和 sync.Cond</h3><pre><code>package main

import (
    "fmt"
    "sync"
    "time"
)

// 单例模式
type singleton struct{}

var instance *singleton
var once sync.Once

func getInstance() *singleton {
    once.Do(func() {
        // 这个函数只会执行一次
        instance = &singleton{}
        fmt.Println("单例创建")
    })
    return instance
}

// 条件变量：用于 goroutine 等待某个条件
func condDemo() {
    var mu sync.Mutex
    cond := sync.NewCond(&mu)

    var ready int

    // 等待者
    for i := 0; i < 3; i++ {
        go func(id int) {
            time.Sleep(time.Duration(id) * 100 * time.Millisecond)

            mu.Lock()
            ready++
            fmt.Printf("等待者 %d 就绪\n", id)
            mu.Unlock()

            // 通知一个等待者
            cond.Signal()
        }(i)
    }

    // 等待所有就绪
    mu.Lock()
    for ready < 3 {
        cond.Wait()
        fmt.Println("收到信号")
    }
    mu.Unlock()
    fmt.Println("所有等待者就绪，继续执行")
}

// Broadcast：广播给所有等待者
func condBroadcast() {
    var mu sync.Mutex
    cond := sync.NewCond(&mu)

    for i := 0; i < 3; i++ {
        go func(id int) {
            mu.Lock()
            cond.Wait()
            mu.Unlock()
            fmt.Printf("等待者 %d 收到广播\n", id)
        }(i)
    }

    time.Sleep(100 * time.Millisecond)

    mu.Lock()
    fmt.Println("发送广播")
    cond.Broadcast()
    mu.Unlock()
}
</code></pre><h2 id="best-practices">最佳实践与性能优化</h2><p>掌握 Go 并发编程的最佳实践可以帮助你编写更安全、更高效的代码。</p><h3>常见错误与避免方法</h3><pre><code>package main

import (
    "context"
    "fmt"
    "sync"
    "time"
)

// 错误1：Goroutine 泄漏
func goroutineLeak() {
    // 创建一个永不关闭的 channel
    ch := make(chan int)

    go func() {
        val := <-ch  // 如果没有人发送，这个 goroutine 永远不会结束
        fmt.Println("收到:", val)
    }()

    // 如果不关闭 ch，不发送数据，goroutine 会泄漏
    // 解决：使用 context 或带超时的 channel
}

// 错误2：死锁
func deadlock() {
    ch := make(chan int)

    // 发送阻塞，因为没有人接收
    ch <- 1  // fatal error: all goroutines are asleep - deadlock!

    // 解决：确保发送和接收在不同的 goroutine 中
}

// 错误3：往已关闭的 channel 发送数据
func closedChannelPanic() {
    ch := make(chan int, 1)
    ch <- 1
    close(ch)

    // 恐慌！
    // ch <- 2  // panic: send on closed channel

    // 正确做法：使用 defer 或 select
    defer func() {
        if r := recover(); r != nil {
            fmt.Println("Recovered:", r)
        }
    }()
}

// 错误4：多个 goroutine 同时修改共享变量
func raceCondition() {
    var count int
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            count++  // 数据竞争！
        }()
    }

    wg.Wait()
    fmt.Println("Count:", count)  // 结果不确定

    // 解决：使用互斥锁或原子操作
}

// 使用原子操作
func atomicCounter() {
    var count int64
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            atomic.AddInt64(&count, 1)
        }()
    }

    wg.Wait()
    fmt.Println("Count:", count)  // 总是 1000
}
</code></pre><h3>并发模式集合</h3><pre><code>package main

import (
    "context"
    "fmt"
    "sync"
    "time"
)

// Pipeline 模式
func pipelineDemo() {
    gen := func(done <-chan struct{}, values ...int) <-chan int {
        out := make(chan int, len(values))
        go func() {
            defer close(out)
            for _, v := range values {
                select {
                case out <- v:
                case <-done:
                    return
                }
            }
        }()
        return out
    }

    square := func(done <-chan struct{}, in <-chan int) <-chan int {
        out := make(chan int)
        go func() {
            defer close(out)
            for v := range in {
                select {
                case out <- v * v:
                case <-done:
                    return
                }
            }
        }()
        return out
    }

    done := make(chan struct{})
    defer close(done)

    for v := range square(done, gen(done, 1, 2, 3, 4, 5)) {
        fmt.Println(v)
    }
}

// Fan-out / Fan-in 模式
func fanOutIn() {
    jobs := make(chan int, 100)
    results := make(chan int, 100)

    // Fan-out: 启动多个 worker
    numWorkers := 3
    var wg sync.WaitGroup

    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            for job := range jobs {
                // 模拟处理时间
                time.Sleep(10 * time.Millisecond)
                results <- job * 2
            }
        }(i)
    }

    // Fan-in: 合并结果
    go func() {
        wg.Wait()
        close(results)
    }()

    // 发送任务
    go func() {
        for i := 1; i <= 20; i++ {
            jobs <- i
        }
        close(jobs)
    }()

    // 收集结果
    for result := range results {
        fmt.Printf("结果: %d\n", result)
    }
}

